A = []
for d in range(m):
    for i in range(W - w[d] + 1):
        A.append((i, i + w[d], d))
for k in range(W):
    A.append((k, k + 1, -1))

out = [[] for _ in range(W + 1)]
for (i, j, d) in A:
    out[i].append((i, j, d))

inc = [[] for _ in range(W + 1)]
for (i, j, d) in A:
    inc[j].append((i, j, d))

D = [[] for _ in range(m)]
for (i, j, d) in A:
    if d >= 0:
        D[d].append((i, j, d))

